// TorrentStats Statistics about torrent activity and performance.
type TorrentStats struct {
	// ActivePeers Number of currently active peers.
	ActivePeers int `json:"active_peers"`

	// BytesHashed Total bytes hashed during verification.
	BytesHashed int64 `json:"bytes_hashed"`

	// BytesRead Total bytes read from disk.
	BytesRead int64 `json:"bytes_read"`

	// BytesReadData Bytes read that contain actual torrent data.
	BytesReadData int64 `json:"bytes_read_data"`

	// BytesReadUsefulData Useful data bytes read from peers.
	BytesReadUsefulData int64 `json:"bytes_read_useful_data"`

	// BytesReadUsefulIntendedData Useful intended data bytes read from peers.
	BytesReadUsefulIntendedData int64 `json:"bytes_read_useful_intended_data"`

	// BytesWritten Total bytes written to disk.
	BytesWritten int64 `json:"bytes_written"`

	// BytesWrittenData Torrent data bytes written to disk.
	BytesWrittenData int64 `json:"bytes_written_data"`

	// ChunksRead Total chunks read from disk.
	ChunksRead int64 `json:"chunks_read"`

	// ChunksReadUseful Useful chunks read from peers.
	ChunksReadUseful int64 `json:"chunks_read_useful"`

	// ChunksReadWasted Wasted chunks read (duplicate or unneeded data).
	ChunksReadWasted int64 `json:"chunks_read_wasted"`

	// ChunksWritten Total chunks written to disk.
	ChunksWritten int64 `json:"chunks_written"`

	// CompletedSize Total size of completed pieces in bytes.
	CompletedSize int64 `json:"completed_size"`

	// ConnectedSeeders Number of connected seeders.
	ConnectedSeeders int `json:"connected_seeders"`

	// HalfOpenPeers Number of peers in half-open state (connecting).
	HalfOpenPeers int `json:"half_open_peers"`

	// InMemory Number of pieces currently loaded in memory.
	InMemory int `json:"in_memory"`

	// InMemorySize Total size of pieces currently in memory in bytes.
	InMemorySize int64 `json:"in_memory_size"`

	// MemoryStats Global memory usage statistics.
	MemoryStats MemoryStats `json:"memory_stats"`

	// MemoryUsagePercentage Percentage of maximum memory used by this torrent (0-100).
	MemoryUsagePercentage float64 `json:"memory_usage_percentage"`

	// MetadataChunksRead Metadata chunks read.
	MetadataChunksRead int64 `json:"metadata_chunks_read"`

	// PendingPeers Number of pending peer connections.
	PendingPeers int `json:"pending_peers"`

	// Pieces Array of all managed pieces with their current status.
	Pieces []PieceInfo `json:"pieces"`

	// PiecesComplete Number of completed pieces.
	PiecesComplete int `json:"pieces_complete"`

	// PiecesDirtiedBad Pieces marked as bad after verification.
	PiecesDirtiedBad int64 `json:"pieces_dirtied_bad"`

	// PiecesDirtiedGood Pieces marked as good after verification.
	PiecesDirtiedGood int64 `json:"pieces_dirtied_good"`

	// Readers Active read stream positions for this torrent.
	Readers *[]ReaderInfo `json:"readers,omitempty"`

	// TotalPeers Total number of known peers.
	TotalPeers int `json:"total_peers"`

	// TotalPieces Total number of pieces in the torrent, from metadata.
	TotalPieces int `json:"total_pieces"`

	// TotalSize Total size of all managed pieces in bytes.
	TotalSize int64 `json:"total_size"`

	// WrittenBytes For memory storage, unique bytes written into currently resident piece buffers. For file storage, torrent bytes completed on disk.
	WrittenBytes int64 `json:"written_bytes"`
}

